<template><div v-loading="loading"><el-tabs v-model="tab" @tab-click="tabChanged"><el-tab-pane label="发药 / 退药" name="orders"><section class="card"><div class="toolbar"><el-input v-model="search" clearable prefix-icon="el-icon-search" placeholder="患者姓名 / 病历号" @keyup.enter.native="page=1;loadOrders()"/><el-button icon="el-icon-search" @click="page=1;loadOrders()">查询</el-button><el-select v-model="filter" class="short-select"><el-option value="pending" label="未发（当前页）"/><el-option value="dispensed" label="已发（当前页）"/><el-option value="returned" label="已退（当前页）"/><el-option value="all" label="全部"/></el-select><el-button icon="el-icon-refresh" @click="loadOrders"/></div><el-table :data="visibleOrders"><el-table-column type="expand"><template slot-scope="s"><div class="expand-info"><span>处方号：{{s.row.prescription_id}}</span><span>医嘱：{{s.row.drug_usage}} · {{s.row.dosage}} · {{s.row.frequency}} · {{s.row.days}}天</span><span>嘱托：{{s.row.notes||'—'}}</span></div></template></el-table-column><el-table-column prop="patient_name" label="患者" width="90"/><el-table-column prop="case_no" label="病历号" min-width="180"/><el-table-column prop="item_name" label="药品" min-width="150"/><el-table-column prop="quantity" label="数量" width="65"/><el-table-column label="金额" width="90"><template slot-scope="s">{{money(s.row.amount_cents)}}</template></el-table-column><el-table-column label="收费" width="95"><template slot-scope="s"><Status :value="s.row.billing_status"/></template></el-table-column><el-table-column label="发放" width="95"><template slot-scope="s"><Status :value="s.row.execution_status" execution/></template></el-table-column><el-table-column label="操作" fixed="right" width="110"><template slot-scope="s"><el-button v-if="s.row.billing_status==='PAID'&&s.row.execution_status==='PENDING'" type="text" :disabled="saving" @click="dispense(s.row)">核对并发药</el-button><el-button v-if="s.row.billing_status==='PAID'&&s.row.execution_status==='DISPENSED'" type="text" class="danger-text" :disabled="saving" @click="returnDrug(s.row)">退回药品</el-button></template></el-table-column></el-table><el-pagination layout="total,prev,pager,next" :total="orders.total" :page-size="20" :current-page.sync="page" @current-change="loadOrders"/></section></el-tab-pane>
<el-tab-pane label="药库查询 / 入库" name="stock"><section class="card"><div class="card-heading"><div><h2>药品库存</h2><p>按编码、名称及拼音组合查询</p></div><el-button aria-label="药品入库" type="primary" icon="el-icon-plus" @click="stockDialog=true">药品入库</el-button></div><div class="toolbar"><el-input v-model="stockSearch.code" clearable placeholder="药品编码"/><el-input v-model="stockSearch.name" clearable placeholder="药品名称"/><el-input v-model="stockSearch.pinyin" clearable placeholder="拼音助记码"/><el-button icon="el-icon-refresh" @click="$emit('catalog-change')"/></div><el-table :data="visibleMedicines"><el-table-column prop="code" label="编码" width="95"/><el-table-column prop="name" label="药品名称" min-width="150"/><el-table-column prop="pinyin" label="拼音" width="90"/><el-table-column prop="unit" label="单位" width="65"/><el-table-column prop="formulation" label="剂型"/><el-table-column prop="manufacturer" label="厂家" min-width="130"/><el-table-column label="单价" width="95"><template slot-scope="s">{{money(s.row.price_cents)}}</template></el-table-column><el-table-column prop="stock" label="库存" width="80"/><el-table-column label="状态" width="80"><template slot-scope="s">{{s.row.active?'启用':'停用'}}</template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane label="药品交易记录" name="movements"><section class="card"><div class="toolbar"><el-input v-model="movementSearch" clearable placeholder="患者姓名 / 病历号 / 药品编码 / 名称" @keyup.enter.native="movementPage=1;loadMovements()"/><el-button icon="el-icon-search" @click="movementPage=1;loadMovements()">查询</el-button></div><el-table :data="movements.items"><el-table-column prop="medicine_name" label="药品" min-width="140"/><el-table-column prop="patient_name" label="患者" width="90"/><el-table-column label="类型" width="80"><template slot-scope="s">{{label(s.row.kind)}}</template></el-table-column><el-table-column prop="quantity" label="数量变化" width="85"/><el-table-column prop="operator_name" label="操作人" width="100"/><el-table-column prop="reason" label="说明" min-width="150"/><el-table-column label="时间" min-width="170"><template slot-scope="s">{{date(s.row.created_at)}}</template></el-table-column></el-table><el-pagination layout="total,prev,pager,next" :total="movements.total" :page-size="20" :current-page.sync="movementPage" @current-change="loadMovements"/></section></el-tab-pane></el-tabs>
<el-dialog title="药品入库" :visible.sync="stockDialog" width="480px"><el-form label-position="top"><el-form-item label="药品"><el-select v-model="stock.medicine_id" filterable><el-option v-for="m in catalog.medicines" :key="m.id" :value="m.id" :label="`${m.code} · ${m.name}`"/></el-select></el-form-item><el-form-item label="入库数量（包装单位）"><el-input-number v-model="stock.quantity" :min="1" :max="1000000"/></el-form-item><el-form-item label="入库依据 / 说明"><el-input v-model="stock.reason" maxlength="500" placeholder="如：采购验收入库单号"/></el-form-item></el-form><span slot="footer"><el-button @click="stockDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="stockIn">确认入库</el-button></span></el-dialog></div></template>
<script>import{api,money,date,label,reason}from'../api';import Status from'../components/Status.vue';export default{components:{Status},props:['catalog'],data:()=>({loading:false,saving:false,tab:'orders',search:'',page:1,orders:{items:[],total:0},filter:'pending',stockSearch:{code:'',name:'',pinyin:''},stockDialog:false,stock:{medicine_id:'',quantity:1,reason:''},movementSearch:'',movementPage:1,movements:{items:[],total:0}}),computed:{visibleOrders(){return this.orders.items.filter(o=>this.filter==='all'||this.filter==='pending'&&o.execution_status==='PENDING'||this.filter==='dispensed'&&o.execution_status==='DISPENSED'||this.filter==='returned'&&o.execution_status==='RETURNED');},visibleMedicines(){return this.catalog.medicines.filter(m=>Object.keys(this.stockSearch).every(k=>String(m[k]||'').toLowerCase().includes(this.stockSearch[k].toLowerCase())));}},created(){this.loadOrders();},methods:{money,date,label,tabChanged(){if(this.tab==='movements')this.loadMovements();},async loadOrders(){this.loading=true;try{this.orders=await api.get('/orders',{params:{kind:'DRUG',q:this.search,page:this.page}});}catch{}finally{this.loading=false;}},async loadMovements(){try{this.movements=await api.get('/stock/movements',{params:{q:this.movementSearch,page:this.movementPage}});}catch{}},async dispense(o){try{await this.$confirm(`核对处方后发放 ${o.item_name} × ${o.quantity}，确认继续？`,'核对发药',{type:'warning'});this.saving=true;await api.post(`/orders/${o.id}/dispense`);this.$message.success('发药成功，库存和交易记录已更新');await this.loadOrders();this.$emit('catalog-change');}catch{}finally{this.saving=false;}},async returnDrug(o){const r=await reason(this,`确认整项退回 ${o.item_name} × ${o.quantity}`);if(!r)return;this.saving=true;try{await api.post(`/orders/${o.id}/return`,{reason:r});this.$message.success('退药已登记，请到收费窗口办理退费');await this.loadOrders();this.$emit('catalog-change');}catch{}finally{this.saving=false;}},async stockIn(){if(!this.stock.medicine_id||!this.stock.reason.trim())return this.$message.warning('请选择药品并填写入库依据');this.saving=true;try{await api.post('/stock/in',this.stock);this.stockDialog=false;this.$message.success('库存已增加，入库流水已保存');this.$emit('catalog-change');this.stock={medicine_id:'',quantity:1,reason:''};}catch{}finally{this.saving=false;}}}};</script>

